export const briefFields=['name','industry','offer','customer','goal','location','contact','story','evidence','funding'];
const limits={name:150,industry:60,offer:1500,customer:500,goal:500,location:300,contact:300,story:1500,evidence:1000,funding:500};
export function cleanBrief(value){
 if(!value||typeof value!=='object'||Array.isArray(value))throw Error('Enter your business brief.');
 const brief={};for(const field of briefFields){const raw=value[field]??'';if(typeof raw!=='string'||raw.length>limits[field])throw Error('Your '+field+' answer is too long or invalid.');brief[field]=raw.trim();}return brief;
}
export function validateBrief(value){const brief=cleanBrief(value);for(const field of ['name','offer','customer','goal','contact'])if(!brief[field])throw Error('Answer the '+field+' question before creating your draft.');if(brief.contact&&!contactURL(brief.contact))throw Error('Use an email, HTTPS link, or WhatsApp number with country code, such as +27.');return brief;}
export function questionFor(field,brief={}){
 const type=(brief.industry||'').toLowerCase();
 const offer=/fashion|cloth|design/.test(type)?'Which garments or design services do you sell? Include made-to-order, sizes and prices only if confirmed.':/food|restaurant|grill|shop/.test(type)?'What can customers buy? Include confirmed prices, collection or delivery options.':/school|educat|train/.test(type)?'What do you teach, who can enrol, and how should learners apply?':'What do you offer, and which customer problem does it solve?';
 return {name:'What is your business or brand name?',industry:'What type of business is it? For example: fashion, services, education, restaurant or shop.',offer,customer:'Who is your ideal customer, and what do they need help with?',goal:'What should visitors do: enquire, book, buy, enrol or contact you?',location:'Where do you serve customers? Leave blank if you work online only.',contact:'Which public contact should appear: an email, WhatsApp number with country code (+27), or HTTPS booking link? Use a confirmed contact customers can reach.',story:'What is your business story or advantage? Include only facts you want customers to see.',evidence:'For your private investor brief: which confirmed sales, demand, costs or results can you show? Leave blank if not yet known.',funding:'For your private investor brief: how much funding do you need and what would it pay for? Leave blank if you are not raising investment.'}[field];
}
export function teamBrief(value){const b=validateBrief(value);return [
 {role:'Business coach',message:'Focus on '+b.customer+'. Your next measurable action is: '+b.goal+'.',question:'What result will you measure after customers use this page?'},
 {role:'Customer advocate',message:'The page needs to explain '+b.offer+' clearly and help visitors '+b.goal+'.',question:'What would stop your customer from taking this next step?'},
 {role:'Investor briefing',message:b.name+' serves '+b.customer+' through '+b.offer+'. '+(b.evidence||'Demand and cost evidence has not been supplied.')+' '+(b.funding||'Funding requirements have not been supplied.'),question:'Which confirmed sales, costs and funding amount can you show an investor?'},
 {role:'Website engineer',message:'Create a responsive page with the offer, story and contact action. Review on phone and laptop before publication.',question:'Do you also need booking, checkout, accounts or live media? Those workflows need their own verified connection.'}
 ];}
export function guidedCopy(value){const b=validateBrief(value);return {headline:b.offer.slice(0,180),introduction:b.story||b.offer,offerTitle:'What we offer',offerDescription:b.offer,customerPitch:'For '+b.customer+'. '+b.offer,investorPitch:b.name+' serves '+b.customer+'. '+b.offer+' '+(b.evidence||'Evidence of traction has not been supplied.')+' '+(b.funding||'Funding requirements have not been supplied.'),advice:'Review your offer, contact details and next action before publishing.'};}
export function cleanCopy(value){const copy={};if(!value||typeof value!=='object')throw Error('The draft response was invalid.');for(const key of ['headline','introduction','offerTitle','offerDescription','customerPitch','investorPitch','advice']){const text=value[key];if(typeof text!=='string'||!text.trim()||text.length>2500)throw Error('The draft response was incomplete or too long.');copy[key]=text.trim();}return copy;}
const esc=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function contactURL(value){const v=value.trim();if(/^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i.test(v))return 'mailto:'+v;if(/^\+?[\d ()-]{8,22}$/.test(v)){const digits=v.replace(/\D/g,'');if(/^[1-9]\d{7,14}$/.test(digits))return 'https://wa.me/'+digits;}try{const u=new URL(v);if(u.protocol==='https:'&&!u.username&&!u.password)return u.href;}catch{}return '';}
export function renderBusinessDraft(value,output){const b=validateBrief(value),c=cleanCopy(output),contact=contactURL(b.contact);
 const html='<main><header><a href="#home">'+esc(b.name)+'</a><nav><a href="#offer">Offer</a>'+(b.story?'<a href="#story">About</a>':'')+'<a href="#contact">Contact</a></nav></header><section id="home" class="hero"><p class="eyebrow">'+esc(b.industry||'Business')+'</p><h1>'+esc(c.headline)+'</h1><p>'+esc(c.introduction)+'</p><a class="button" href="#contact">'+esc(b.goal)+'</a></section><section id="offer"><p class="eyebrow">For '+esc(b.customer)+'</p><h2>'+esc(c.offerTitle)+'</h2><p>'+esc(c.offerDescription)+'</p></section>'+(b.story?'<section id="story"><h2>Our story</h2><p>'+esc(b.story)+'</p></section>':'')+'<section id="contact"><h2>'+esc(b.goal)+'</h2>'+(b.location?'<p>'+esc(b.location)+'</p>':'')+(contact?'<a class="button" href="'+esc(contact)+'">'+esc(b.contact)+'</a>':'<p>Contact details will be added before launch.</p>')+'</section><footer>'+esc(b.name)+'</footer></main>';
 const css=':root{color-scheme:dark;font-family:system-ui,sans-serif;background:#0b0b0b;color:#fff}*{box-sizing:border-box}body{margin:0}main{max-width:1200px;margin:auto}header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:24px;flex-wrap:wrap}header>a{font-weight:800}nav{display:flex;gap:24px}a{color:#d4af37;text-decoration:none}section{padding:60px 24px;scroll-margin-top:20px}h1{font-size:clamp(32px,6vw,72px);line-height:1.1;max-width:950px;overflow-wrap:anywhere}h2{font-size:32px}p{line-height:1.7;max-width:800px;white-space:pre-wrap;overflow-wrap:anywhere}.hero{min-height:60vh;display:flex;flex-direction:column;justify-content:center}.eyebrow{color:#d4af37}.button{display:inline-block;background:#d4af37;color:#0b0b0b;border-radius:8px;padding:16px 22px;align-self:start;font-weight:700;overflow-wrap:anywhere}#offer{background:#171717}footer{padding:24px;color:#d4af37}a:focus-visible{outline:2px solid #fff;outline-offset:5px}@media(max-width:600px){section{padding:36px 20px}header{padding:20px}nav{gap:18px}}';
 return {name:b.name,html,css,brief:b};
}
export function appPlan(value){const b=validateBrief(value);return {business:b.name,customer:b.customer,goal:b.goal,status:'Implementation plan, not a generated native application',screens:[{name:'Home',purpose:'Explain '+b.offer},{name:'Offer',purpose:'Present confirmed products or services'},{name:'Contact',purpose:b.goal}],workflows:['Choose an offer','Review confirmed details',b.goal],connections:['Define and verify payment, booking or account services before enabling those actions'],brief:b};}
